{"description":"Analyze FPbase data for ex505/em610 and candidate names","cmd":"python3 << 'EOF'
import json
data=json.load(open('/tmp/fpbase.json'))

def states(p):
    out=[]
    for s in p.get('states', []):
        out.append((s.get('name'), s.get('ex_max'), s.get('em_max'), s.get('slug')))
    return out

# Print proteins with an ex_max between 490-520 and em_max between 590-630
print("=== Proteins with ex_max 490-520 AND em_max 580-630 ===")
for p in data:
    for (nm, ex, em, sl) in states(p):
        if ex and em and 490 <= ex <= 520 and 580 <= em <= 630:
            print(f"{p['name']:30s} state={nm:25s} ex={ex} em={em} slug={p['slug']}")
            break

print()
print("=== Search candidates from PDB list by name ===")
for name in ['TagRFP675','PSmOrange','mCherry','AzamiGreen','TagRFP','GFP','eGFP','PSmOrange','5JZL','5WJ2','6AA7','3MGF','5Y01','2VZX','1H6R']:
    for p in data:
        if name.lower() in p['name'].lower() or name.lower() in p['slug']:
            print(f"FOUND {p['name']} ({p['slug']})")
            for st in states(p):
                print(f"    state={st[0]!r} ex={st[1]} em={st[2]}")
            break
EOF","yield_time_ms":30000}

