{"description":"Get FPbase states for candidate FPs","cmd":"python3 << 'EOF'
import json
fp=json.load(open('/tmp/fpbase.json'))
targets=['muGFP','usGFP','vsGFP','Clover','Clover1.5','mClover1.5','Gamillus','mCherry','AdRed','mKO','Dendra','Dendra2','TagRFP','TagRFP675','PSmOrange','mAzamiGreen','AzamiGreen','cjBlue','HcRed','GFPmut2','EYFP']
by={}
for p in fp:
    by[p['name'].lower()]=p
for t in targets:
    p=by.get(t.lower())
    if not p:
        print(f"{t}: NOT FOUND"); continue
    print(f"=== {p['name']} ({p['slug']}) ===")
